// Test double for `@oh-my-pi/pi-utils` inside compiled changelog bundles.
// Generated from the bundle's import graph; every export is a no-op stand-in
// except the changelog-path surface faked below, so the compiled binary
// contains no real changelog implementation (the heap probe asserts that).
import packageJson from "../../package.json" with { type: "json" };

export const VERSION = packageJson.version;
export const getLastChangelogVersionPath = (): string => "";
export const getChangelogPath = (): string | undefined => undefined;
export const isEnoent = (error: unknown): boolean =>
	typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT";
export const logger = { error: () => {}, warn: () => {} };
export const parseFlag = (value: string | undefined, def = false): boolean => def;
export const getProjectDir = (): string | undefined => undefined;

